create table if not exists public.endurance_experiments(
 id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,race_goal_id uuid references public.endurance_race_goals(id) on delete set null,
 variable text not null check(variable in ('sessions_per_week','long_run_weekday','recovery_day_spacing')),hypothesis text not null,baseline_value text not null,test_value text not null,
 primary_metric text not null check(primary_metric in ('session_completion','distance_completion','self_reported_response','running_efficiency')),duration_weeks integer not null check(duration_weeks between 2 and 8),
 started_on date not null,ends_on date not null,status text not null default 'active' check(status in ('active','completed','cancelled')),protocol_snapshot jsonb not null,created_at timestamptz not null default now()
);
create unique index if not exists endurance_one_active_experiment_per_user on public.endurance_experiments(user_id) where status='active';
alter table public.endurance_experiments enable row level security;revoke all on table public.endurance_experiments from anon;grant select on table public.endurance_experiments to authenticated;grant all on table public.endurance_experiments to service_role;
create policy "Users read own endurance experiments" on public.endurance_experiments for select to authenticated using((select auth.uid())=user_id);
create table if not exists public.endurance_experiment_results(id uuid primary key default gen_random_uuid(),experiment_id uuid not null references public.endurance_experiments(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,result jsonb not null,created_at timestamptz not null default now(),unique(experiment_id));
alter table public.endurance_experiment_results enable row level security;revoke all on table public.endurance_experiment_results from anon;grant select on table public.endurance_experiment_results to authenticated;grant all on table public.endurance_experiment_results to service_role;create policy "Users read own endurance experiment results" on public.endurance_experiment_results for select to authenticated using((select auth.uid())=user_id);
